const EndShot: React.FC<{ f: number; p: AppLaunchProps }> = ({ f, p }) => {
  const atLine = stretch(CLOSE_AT, p.closing.length);
  const typed = f < 1104 ? atLine.filter((a) => a <= f).length : Math.round((tbl(f, CLOSE_LEFT) / 29) * p.closing.length);
