          opacity: markIn, transform: `scale(${0.9 + 0.1 * markIn})`, filter: `drop-shadow(0 0 ${18 * markIn}px rgba(255,236,230,0.55))`,
          WebkitMaskImage: `linear-gradient(to top, black ${markIn * 100}%, transparent ${markIn * 100 + 25}%)` }}>
