/** The glow under each framing: strength (and which side it leans), from the spec's bottom-corner samples. */
const glowFor = (f: number) => {
  if (f < 298) return { a: tbl(f, [[197, 0.72], [200, 0.6], [210, 0.48], [230, 0.36], [255, 0.2], [297, 0.17]]), flip: false };
  if (f < 362) return { a: tbl(f, [[298, 0.3], [361, 0.55]]), flip: true };
  return { a: tbl(f, [[362, 0.33], [385, 0.4], [394, 0.5], [397, 0.6], [410, 0.45], [423, 0.3]]), flip: true };
};

export interface BarShotProps {
  f: number;
  palette: RisePalette;
  prompt: string;
  chips: string[];
  /** the chips' glyphs (shapes by default) */
  chipIcons?: ChipIcon[];
  /** the mark in the bar's leading slot: a letter, or our K when empty */
  mark?: string;
}

export const BarShot: React.FC<BarShotProps> = ({ f, palette, prompt, chips, chipIcons = DEFAULT_ICONS, mark }) => {
  const cam = camera(f);
  const g = glowFor(f);
  const fall = f >= 362 ? tbl(f, DROP_C) : 0;
  const flash = tbl(f, [[393, 0], [395, 0.03], [396, 0.05], [397, 0.1], [398, 0.1], [400, 0.07], [405, 0.04], [411, 0]]);
  const markIn = f >= 205 && f < 240;
  const markScale = 1 - 0.32 * 0.88 ** Math.max(0, f - 208);
  const markA = f < 226 ? 1 : 1 - 0.055 * (f - 226);
  const markDx = tbl(f, [[222, 0], [225, 2.5], [226, 4], [227, 5], [228, 7.5], [229, 9.5], [230, 12.5], [236, 47], [237, 56], [238, 68], [239, 85]]) / 1.808;
  const markBlur = f < 216 ? tbl(f, [[205, 4], [212, 3.3], [216, 1]]) : tbl(f, [[226, 0.8], [232, 2.2], [238, 3.3]]);
  const outlineA = f < 298 ? tbl(f, [[211, 0], [215, 1]]) : 1;
  return (
    <AbsoluteFill style={{ background: RISE_PALETTES[palette][0], overflow: 'hidden' }}>
      {/* the glow, riding the camera's fall in C */}
      <AbsoluteFill style={{ opacity: g.a, transform: `translateY(${fall}px) scaleX(${g.flip ? -1 : 1})` }}>
        <div style={{ width: 1920, height: 1080, transform: `scale(${W / 1920}, ${H / 1080})`, transformOrigin: '0 0' }}>
          <RiseGlow {...riseGlowDefaults} palette={palette} ring={0} height={1.25} />
        </div>
      </AbsoluteFill>

      {f < 298 && <Guides f={f} bl={cam.ty + BH * cam.z} />}

      {/* the bar and everything in it, framed by the camera */}
      <div style={{ position: 'absolute', left: 0, top: 0, width: BW, height: BH, transform: `translate(${cam.tx}px, ${cam.ty}px) scale(${cam.z})`, transformOrigin: '0 0' }}>
        <div
          style={{
            position: 'absolute',
            left: 0,
            top: 0,
            width: BW,
            height: BH,
            borderRadius: BH / 2,
            boxSizing: 'border-box',
            border: `${f < 298 ? 1.1 : f < 362 ? 1 : 0.95}px solid ${LINE}`,
            opacity: outlineA,
          }}
        />
        {[0, 1, 2, 3].map((i) => <Chip key={i} f={f} i={i} name={chips[i] ?? ''} icon={chipIcons[i] ?? 'dots'} />)}
        {markIn && (
          <div
            style={{
              position: 'absolute',
              left: MARK.x - MARK.w / 2 + markDx,
              top: MARK.y - MARK.h / 2,
              transform: `scale(${markScale})`,
              opacity: clamp01(markA),
              filter: `blur(${markBlur / 1.808}px)`,
            }}
          >
            <Mark letter={mark} />
          </div>
        )}
        <Plus f={f} />
        <Prompt f={f} text={prompt} />
        {f >= 298 && <Send f={f} />}
      </div>

      <Cursor f={f} cam={cam} />
      {flash > 0 && <AbsoluteFill style={{ background: '#ffd8c8', opacity: flash, mixBlendMode: 'screen' }} />}
    </AbsoluteFill>
  );
};

// Prompt Intro: a 3.3 s opener for a product film. An arrow with a soft halo shrinks and slides left, a prompt types on
// beside it (letters land blurred and settle, a warm tint sweeps along behind the typing), three dots trail it; the arrow
// dips back, launches right and the prompt deletes itself into the next line while a blue flash washes over the frame and
// the glow at the bottom flares orange; the answer types on with an amber first word, a second arrow glides in after it,
// and everything drops out of frame for the cut.
//
// Built from the measured opening of a SaaS launch reel with the kinetograph-taste-clone skill: every motion is the
// reference's own per-frame table (f0-f196), so the timing, eases and
// layout are the reference's; the words, the font and the glow are ours. The glow is the RiseGlow background with any of
// its palettes (liquid by default); the typing rhythm is the reference's, stretched to the length of your lines.
//
// Principles: anticipation (the arrow dips before it launches), slow in and out (every move is a measured ease), overlap
// (the tint trails the typing, the dots trail the line), staging (one line at a time), follow through (the answer settles
// from 1.29x after it lands).

import React from 'react';
import { z } from 'zod';
import { AbsoluteFill, useCurrentFrame } from 'remotion';
import { loadFont } from '@remotion/google-fonts/Comfortaa';
import { measureText } from '@remotion/layout-utils';
import { RISE_PALETTES, RiseGlow, riseGlowDefaults, type RisePalette } from './shared/components/backgrounds/rise-glow.js';

export const W = 1920;
export const H = 1080;
export const FPS = 60;
export const DURATION = 197;

const FONT = loadFont('normal', { weights: ['400', '700'] }).fontFamily;

const hexC = z.string().describe('A CSS colour as #rrggbb.');

export const promptIntroSchema = z.object({
  prompt: z.string().min(1).max(40).describe('The first line, typed then deleted (the reference: 29 characters).'),
  answer: z.string().min(1).max(40).describe('The second line; its first word lands amber (the reference: 28 characters).'),
  palette: z.enum(Object.keys(RISE_PALETTES) as [RisePalette, ...RisePalette[]]).describe('The glow at the bottom: a RiseGlow palette.'),
  ink: hexC.describe('The text and arrows.'),
  tint: hexC.describe('The tint that sweeps along the typing.'),
  flash: z.boolean().describe('The blue flash and orange flare as the prompt deletes.'),
});
export type PromptIntroProps = z.infer<typeof promptIntroSchema>;

export const promptIntroDefaults: PromptIntroProps = {
  prompt: 'I need a film for my business',
  answer: 'Stop cutting reels manually.',
  palette: 'liquid',
  ink: '#edebef',
  tint: '#e0b4b8',
  flash: true,
