/** The reference's landing frames stretched to a line of n characters. */
const stretch = (at: number[], n: number) =>
  Array.from({ length: n }, (_, i) => at[Math.min(at.length - 1, Math.round((i * (at.length - 1)) / Math.max(1, n - 1)))]);

const width = (text: string) => measureText({ text, fontFamily: FONT, fontSize: SIZE, fontWeight: 400 }).width;

// ---------------------------------------------------------------- pieces

const Arrow: React.FC<{ cx: number; cy: number; s: number; ink: string; flip?: boolean; opacity?: number; halo?: number }> = ({
  cx, cy, s, ink, flip, opacity = 1, halo = 0,
}) => (
  <svg
    width={143}
    height={111}
    viewBox="0 0 143 111"
    style={{
      position: 'absolute',
      left: cx - 71.5,
      top: cy - 55.5,
      transform: `scale(${flip ? -s : s}, ${s})`,
      opacity,
      filter: halo > 0.01 ? `drop-shadow(0 0 14px ${rgba(ink, 0.55 * halo)}) drop-shadow(0 0 60px ${rgba(ink, 0.3 * halo)})` : undefined,
    }}
  >
    <path d="M4 55.5 H132 M84 8.5 L131 55.5 L84 102.5" fill="none" stroke={ink} strokeWidth={17} strokeLinecap="butt" strokeLinejoin="miter" />
  </svg>
);

interface LineProps {
  f: number;
  text: string;
  at: number[];
  scale: Table;
  cx: Table;
  sweep: Table;
  sweepEnd: number;
  ink: string;
  tint: string;
  dy?: number;
  alpha?: number;
  count?: number;
  amberUntil?: number;
}

const Line: React.FC<LineProps> = ({ f, text, at, scale, cx: cxT, sweep, sweepEnd, ink, tint, dy = 0, alpha = 1, count, amberUntil }) => {
  const n = count ?? at.filter((a) => a <= f).length;
  if (n <= 0) return null;
  const s = tbl(f, scale);
  const cx = tbl(f, cxT);
  const full = width(text);
  const shown = width(text.slice(0, n));
  const sweepX = f < sweepEnd ? cx - (shown / 2) * s + tbl(f, sweep) * full * s : -9999;
  const firstWord = text.indexOf(' ') < 0 ? text.length : text.indexOf(' ');
  return (
    <div
      style={{
        position: 'absolute',
        left: 0,
        width: W,
        top: CY - 40 + dy,
        height: 80,
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        transform: `translateX(${cx - W / 2}px) scale(${s})`,
        transformOrigin: `${W / 2}px 40px`,
        opacity: alpha,
      }}
    >
      {text.slice(0, n).split('').map((ch, i) => {
        const age = f - at[i];
        const t = clamp01(age / 9);
        const ls = 1.2 - 0.2 * (1 - (1 - t) ** 2);
        const blur = 6 * (1 - t);
        const x = cx + (width(text.slice(0, i)) + width(ch) / 2 - shown / 2) * s;
        const band = clamp01(1 - Math.abs(x - sweepX) / 220);
        const amber = amberUntil !== undefined && f < amberUntil && i < firstWord;
        const color = amber ? mix('#fbe6c0', '#e49d74', clamp01(age / 12)) : mix(ink, tint, band);
        return (
          <span
            key={i}
            style={{
              display: 'inline-block',
              whiteSpace: 'pre',
              fontFamily: FONT,
              fontWeight: amber || band > 0.5 ? 700 : 400,
              fontSize: SIZE,
              lineHeight: '80px',
              color,
              transform: `scale(${ls})`,
              transformOrigin: '50% 60%',
              filter: blur > 0.2 ? `blur(${blur}px)` : undefined,
              textShadow: amber ? '0 0 4px rgba(250,207,147,0.9), 0 0 9px rgba(202,136,96,0.6)' : undefined,
            }}
          >
            {ch}
          </span>
        );
      })}
    </div>
  );
};

// ---------------------------------------------------------------- the film

export const PromptIntro: React.FC<PromptIntroProps> = (p) => {
  const f = useCurrentFrame();
  const pal = RISE_PALETTES[p.palette];
  const ground = pal[0];
  const k = p.flash ? tbl(f, FLASH) : 0;
  const dy = tbl(f, FALL);
  const drop = tbl(f, GLOW_DROP) + dy;

  // where our lines sit against the reference's: the arrow, the dots and the second arrow keep the reference's gaps
  const w1 = width(p.prompt);
  const w2 = width(p.answer);
  const left1 = 952 - (w1 * 1.05) / 2; // the prompt's left edge at f60 (the reference's: 564)
  const right1 = 952 + (w1 * 1.05) / 2; // its right edge (the reference's: 1340)
  const right2 = 956 + w2 / 2; // the answer's right edge, settled (the reference's: 1310)
  const a1dx = (left1 - 564) * clamp01((f - 20) / 20) * (1 - clamp01((f - 86) / 8));
  const ddx = (right1 + 26 - 1366) * (1 - clamp01((f - 86) / 7));

  // the ring lifts the ground toward the palette's edge colour by at most 0.05 a channel
  const [g0, g1] = [hex(ground), hex(pal[1])];
  const kk = Math.min(0.3, 12.75 / Math.max(1, ...g1.map((v, i) => Math.abs(v - g0[i]))));
  const ringC = `rgb(${g0.map((v, i) => Math.round(v + (g1[i] - v) * kk)).join(',')})`;
  const ri = tbl(f, RING_IN);
  const ro = tbl(f, RING_OUT);

  const n1 = p.prompt.length;
  const at1 = stretch(REF1.at, n1);
  const at2 = stretch(REF2.at, p.answer.length);

  const dotsN = f < 49 ? 1 : f < 75 ? 2 : 3;
  const deleting = f >= 86;
  const dotSize = deleting ? 5 : tbl(f, [[25, 12], [37, 9]]);
  const pitch = deleting ? 9 : tbl(f, [[49, 33], [52, 28], [56, 24], [60, 22]]);

  return (
    <AbsoluteFill style={{ background: ground, overflow: 'hidden' }}>
      {/* the glow */}
      <AbsoluteFill style={{ transform: `translateY(${drop}px)`, filter: `brightness(${tbl(f, GAIN)})` }}>
        <RiseGlow {...riseGlowDefaults} palette={p.palette} ring={0} speed={0.6} height={0.85} />
      </AbsoluteFill>
      <AbsoluteFill style={{ opacity: k, background: 'linear-gradient(to bottom, #28527e 0%, #28527e 62%, rgba(40,82,126,0) 86%)' }} />
      <AbsoluteFill
        style={{
          opacity: 1 - clamp01((f - 70) / 10),
          background: `radial-gradient(circle at 0px 540px, transparent ${ri - 3}px, ${ringC} ${ri + 3}px, ${ringC} ${ro - 3}px, transparent ${ro + 3}px)`,
          mixBlendMode: 'lighten',
        }}
      />
      <AbsoluteFill style={{ transform: `translateY(${drop}px)` }}>
        {/* after the flash the glow swells into one broad lobe right of centre */}
        <AbsoluteFill
          style={{
            opacity: tbl(f, POST),
            filter: `brightness(${tbl(f, [[136, 1], [176, 1.15]])})`,
            background: [
              `radial-gradient(ellipse 62% 50% at 70% 106%, ${rgba(pal[4], 0.9)} 0%, ${rgba(pal[3], 0.8)} 22%, ${rgba(pal[2], 0.6)} 50%, ${rgba(pal[1], 0.3)} 76%, ${rgba(ground, 0)} 100%)`,
            ].join(','),
          }}
        />
        {p.flash && (
          <AbsoluteFill
            style={{
              opacity: tbl(f, FLARE),
              background: [
                'radial-gradient(ellipse 34% 34% at 25% 104%, #f6c056 0%, #f0890f 30%, #e0503a 58%, rgba(70,130,150,0.5) 80%, rgba(40,82,126,0) 100%)',
                'radial-gradient(ellipse 34% 30% at 75% 106%, #f6c056 0%, #f0890f 30%, #e0503a 58%, rgba(70,130,150,0.5) 80%, rgba(40,82,126,0) 100%)',
                'linear-gradient(to top, #f0890f 0%, #e0503a 9%, rgba(80,120,150,0.4) 17%, rgba(40,82,126,0) 24%)',
              ].join(','),
            }}
          />
        )}
      </AbsoluteFill>

      {/* the prompt, then its deletion */}
      {f < 93 && (
        <Line
          f={f}
          text={p.prompt}
          at={at1}
          scale={REF1.scale}
          cx={REF1.cx}
          sweep={REF1.sweep}
          sweepEnd={REF1.sweepEnd}
          ink={p.ink}
          tint={p.tint}
          count={deleting ? Math.max(1, Math.round(n1 * tbl(f, REF1.left))) : undefined}
          alpha={deleting ? tbl(f, [[86, 0.85], [92, 0.6]]) : 1}
        />
      )}
      {f >= 25 && f < 93 &&
        Array.from({ length: dotsN }, (_, i) => (
          <div
            key={i}
            style={{
              position: 'absolute',
              left: tbl(f, D1_X) + ddx + i * pitch,
              top: 553 - dotSize,
              width: dotSize,
              height: dotSize + (deleting ? 0 : 1),
              borderRadius: 2,
              background: p.ink,
              opacity: deleting ? 0.6 : 1,
            }}
          />
        ))}

      {/* the answer */}
      {f >= 93 && (
        <Line
          f={f}
          text={p.answer}
          at={at2}
          scale={REF2.scale}
          cx={REF2.cx}
          sweep={REF2.sweep}
          sweepEnd={REF2.sweepEnd}
          ink={p.ink}
          tint={p.tint}
          dy={dy}
          amberUntil={110}
        />
      )}

      {/* the arrows */}
      {f < 112 && (
        <Arrow
          cx={tbl(f, A1_CX) + a1dx}
          cy={CY}
          s={tbl(f, A1_S)}
          ink={p.ink}
          halo={tbl(f, [[0, 1], [6, 0.9], [11, 0.5], [16, 0]])}
          opacity={k > 0 ? tbl(f, [[82, 1], [85, 0.7], [89, 0.55], [100, 0.55], [104, 1]]) : 1}
        />
      )}
      {f >= 139 && <Arrow cx={tbl(f, A2_L) + 27.5 + (right2 - 1310)} cy={CY + 1 + dy} s={0.385} ink={p.ink} flip />}
    </AbsoluteFill>
  );
};

// Aurora Veil: soft curtains of colour drifting across the frame like the northern lights, after the Aurora background
// on shadcn.io. Two bands of repeating colour stripes, skewed 12 degrees, slide past each other in opposite directions
// (one stripe every 10 s and every 17 s), over a faint wash that fills the gaps. The layer fades out from the top right
// corner and sits at an opacity set by `intensity`, paler on a light ground and brighter on a dark one.
//
// It is one fragment shader: each pixel is un-skewed into the curtain box, sampled from the two stripe gradients and the
// wash (premultiplied, as a browser composites them), masked by the corner ellipse and laid over the ground. The drift is
// a pure function of the frame.
//
// Principles: restraint (two bands, no blur, no flicker), overlap (two periods that never line up), slow in and out
// (nothing starts or stops; the motion is constant like the real thing), staging (the fade keeps one corner lit and the
// rest of the frame free for content).

import React from 'react';
import { z } from 'zod';
import { GlslShader } from '@kinetographdev/core';
import { useCurrentFrame } from 'remotion';
import { rgb } from './lib.js';

export const W = 1920;
export const H = 1080;
export const FPS = 30;

const hex = z.string().describe('A CSS colour as #rrggbb.');

export const auroraVeilSchema = z.object({
  colors: z
    .array(hex)
    .min(1)
    .max(5)
    .describe('Up to five curtain colours, repeated when there are fewer. The third is the brightest band.'),
  mode: z.enum(['dark', 'light']).describe('Dark or light ground; the curtains are brighter on dark.'),
  ground: hex.describe('Ground colour. Leave empty to use the mode default (#0a0a0a dark, #ffffff light).').or(z.literal('')),
  intensity: z.enum(['subtle', 'medium', 'strong']).describe('How strongly the curtains show over the ground.'),
  fade: z.boolean().describe('Fade the curtains out from the top-right corner; off fills the whole frame.'),
  speed: z.number().min(0).max(6).describe('Drift speed: 2 is twice as fast, 0.5 half as fast.'),
});
export type AuroraVeilProps = z.infer<typeof auroraVeilSchema>;

export const auroraVeilDefaults: AuroraVeilProps = {
  // emerald, bright emerald, mint, light teal, teal
  colors: ['#00bc7d', '#00d492', '#5ee9b5', '#00d5be', '#00bba7'],
  mode: 'dark',
  ground: '',
  intensity: 'medium',
  fade: true,
  speed: 1,
};

/** The layer's opacity per intensity, [light, dark]. */
const INTENSITY = { subtle: [0.4, 0.5], medium: [0.6, 0.75], strong: [0.8, 0.95] } as const;

const FRAGMENT = `
precision highp float;
uniform vec2 u_res;
uniform float u_t;
uniform vec3 u_bg;
uniform vec3 u_c1; uniform vec3 u_c2; uniform vec3 u_c3; uniform vec3 u_c4; uniform vec3 u_c5;
uniform float u_opacity;
uniform float u_fade;

// a colour at an alpha, premultiplied
vec4 pm(vec3 c, float a){ return vec4(c * a, a); }

// a gradient through stops (position, premultiplied colour), clamped at both ends
vec4 ramp4(float x, float p0, vec4 s0, float p1, vec4 s1, float p2, vec4 s2, float p3, vec4 s3){
  if (x <= p0) return s0;
  if (x < p1) return mix(s0, s1, (x - p0) / (p1 - p0));
  if (x < p2) return mix(s1, s2, (x - p1) / (p2 - p1));
  if (x < p3) return mix(s2, s3, (x - p2) / (p3 - p2));
  return s3;
}
vec4 ramp5(float x, float p0, vec4 s0, float p1, vec4 s1, float p2, vec4 s2, float p3, vec4 s3, float p4, vec4 s4){
  if (x < p3) return ramp4(x, p0, s0, p1, s1, p2, s2, p3, s3);
  if (x < p4) return mix(s3, s4, (x - p3) / (p4 - p3));
  return s4;
}
vec4 over(vec4 src, vec4 dst){ return src + dst * (1.0 - src.a); }

void main(){
  float Wd = u_res.x; float Hd = u_res.y;
  // CSS pixels: x right, y down
  vec2 p = vec2(gl_FragCoord.x, Hd - gl_FragCoord.y);
  // undo skewX(-12deg) about the box centre
  float k = tan(radians(12.0));
  float xl = p.x + k * (p.y - Hd * 0.5);
  // the box runs 11% of the height past each side
  float bw = Wd + 0.22 * Hd;
  float u = xl + 0.11 * Hd;

  vec4 none = vec4(0.0);
  // the wash under the bands
  vec4 wash = ramp4(u / bw, 0.0, pm(u_c1, 0.18), 1.0/3.0, pm(u_c4, 0.22), 2.0/3.0, pm(u_c3, 0.14), 1.0, pm(u_c5, 0.22));

  // band A: stripes a quarter of the box wide, sliding left one stripe every 10 s
  float sA = 0.25 * bw;
  float tA = fract(u_t / 10.0) * sA;
  float fa = fract((u + tA) / sA);
  vec4 bandA = ramp5(fa, 0.08, none, 0.30, pm(u_c1, 0.6), 0.48, pm(u_c3, 1.0), 0.62, pm(u_c4, 0.7), 0.88, none);

  // band B: stripes a fifth of the box wide, starting 20% to the left, sliding right one stripe every 17 s
  float sB = 0.2 * bw;
  float tB = fract(u_t / 17.0) * sB;
  float fb = fract((u + 0.2 * bw - tB) / sB);
  vec4 bandB = ramp4(fb, 0.15, none, 0.40, pm(u_c2, 0.55), 0.55, pm(u_c5, 0.8), 0.80, none);

  vec4 layer = over(bandB, over(bandA, wash));

  // the fade: an ellipse at the top-right corner, through the far corner, solid to 10% and gone by 75%
  float d = length(vec2((p.x - Wd) / (Wd * 1.41421356), p.y / (Hd * 1.41421356)));
  float mask = mix(1.0, 1.0 - clamp((d - 0.10) / 0.65, 0.0, 1.0), u_fade);

  float a = u_opacity * mask;
  vec3 col = u_bg * (1.0 - layer.a * a) + layer.rgb * a;
  gl_FragColor = vec4(col, 1.0);
}
`;

export const AuroraVeil: React.FC<AuroraVeilProps> = (p) => {
  const frame = useCurrentFrame();
  const c = (n: number) => rgb(p.colors[n % p.colors.length]);
  const dark = p.mode === 'dark';
  const ground = p.ground || (dark ? '#0a0a0a' : '#ffffff');
  return (
    <GlslShader
      id="av-shader"
      width={W}
      height={H}
      fragment={FRAGMENT}
      uniforms={{
        u_res: [W, H],
        u_t: (frame / FPS) * p.speed,
        u_bg: rgb(ground),
        u_c1: c(0), u_c2: c(1), u_c3: c(2), u_c4: c(3), u_c5: c(4),
        u_opacity: INTENSITY[p.intensity][dark ? 1 : 0],
        u_fade: p.fade ? 1 : 0,
      }}
    />
  );
};

// Aurora / Silk: slow light ribbons over a deep ground, drawn by a fragment shader. Each ribbon is a soft band that
// follows two sines, brighter on its upper edge and fading below, with a thin sheen along its crest like creased silk.
// Colours pass along each ribbon, and the ribbons combine by screening, so two overlapping never blow out.
//
// Principles: slow in and out (sines), overlap and follow through (each ribbon has its own phase and a slower second
// harmonic that trails the first), arcs, restraint (low intensity: it sits behind type), solid drawing (one glow side).

import React from 'react';
import { z } from 'zod';
import { GlslShader, Layer, grain } from '@kinetographdev/core';
import { useCurrentFrame } from 'remotion';
import { NOISE_GLSL, phase, rgb } from './lib.js';

export const W = 1920;
export const H = 1080;
export const FPS = 30;
export const DURATION = 300;

const hex = z.string().describe('A CSS colour.');

export const auroraSchema = z.object({
  groundTop: hex.describe('The ground at the top.'),
  groundBottom: hex.describe('The ground at the bottom.'),
  ribbons: z.array(hex).length(3).describe('Three ribbon colours, which also blend along each ribbon.'),
  intensity: z.number().min(0).max(1.5).describe('How bright the ribbons are. 0.6 sits behind type; 1 is bold.'),
  width: z.number().min(0.4).max(2.5).describe('How wide the ribbons are, as a multiple of the default.'),
  speed: z.number().min(0).max(4).describe('How fast they flow. Whole numbers loop seamlessly over 10 seconds.'),
  scale: z.number().min(0.4).max(3).describe('How long the waves are, as a multiple of the default. Higher is calmer.'),
  grain: z.number().min(0).max(0.3).describe('Grain amount over the whole frame.'),
});
export type AuroraProps = z.infer<typeof auroraSchema>;

export const auroraDefaults: AuroraProps = {
  groundTop: '#050912',
  groundBottom: '#0d1626',
  ribbons: ['#2fd3b0', '#7a6bff', '#4aa3ff'],
  intensity: 1.15,
  width: 1,
  speed: 1,
  scale: 1,
  grain: 0.07,
};

const FRAGMENT = `
precision highp float;
uniform vec2 u_res;
uniform float u_ph;
uniform vec3 u_g0; uniform vec3 u_g1;
uniform vec3 u_c0; uniform vec3 u_c1; uniform vec3 u_c2;
uniform float u_int; uniform float u_w; uniform float u_scale;
${NOISE_GLSL}
vec3 ribbonColour(float t){
  t = clamp(t, 0.0, 1.0) * 2.0;
  return t < 1.0 ? mix(u_c0, u_c1, t) : mix(u_c1, u_c2, t - 1.0);
}
void main(){
  vec2 uv = gl_FragCoord.xy / u_res;
  float asp = u_res.x / u_res.y;
  vec2 p = vec2(uv.x * asp, uv.y);
  vec3 col = mix(u_g1, u_g0, uv.y);
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float k = (1.1 + 0.35 * fi) / u_scale;
    float base = 0.30 + 0.115 * fi;
    float y = base
      + 0.085 * sin(p.x * k * 2.0 + u_ph + fi * 1.7)
      + 0.045 * sin(p.x * k * 4.1 - u_ph * 2.0 + fi * 2.9)
      + 0.02 * sin(p.x * k * 7.3 + u_ph * 3.0 + fi * 0.6);
    float d = p.y - y;
    float w = (d > 0.0 ? 0.050 : 0.17) * u_w * (0.8 + 0.2 * sin(p.x * 1.3 + fi + u_ph));
    float body = exp(-(d * d) / (w * w));
    float sheen = exp(-(d * d) / (w * w * 0.012)) * 0.35;
    float fade = 0.55 + 0.45 * sin(p.x * (0.9 + 0.2 * fi) + fi * 2.0 + u_ph);
    float tone = 0.5 + 0.5 * sin(p.x * 0.8 + fi * 1.3 - u_ph);
    vec3 rc = ribbonColour(tone * 0.6 + fi * 0.13);
    float I = (body * 0.55 + sheen) * fade * u_int * (0.8 - 0.1 * fi);
    col = 1.0 - (1.0 - col) * (1.0 - clamp(rc * I, 0.0, 1.0));
  }
  col += (vnoise(gl_FragCoord.xy * 0.5) - 0.5) * 0.012;
  float v = smoothstep(1.25, 0.35, length((uv - 0.5) * vec2(1.0, 0.85)));
  col *= 0.78 + 0.22 * v;
  gl_FragColor = vec4(col, 1.0);
}
`;

export const Aurora: React.FC<AuroraProps> = (p) => {
  const frame = useCurrentFrame();
  const ph = phase(frame, DURATION, p.speed);
  return (
    <Layer id="au-root" effects={p.grain > 0 ? [grain(p.grain, { seed: 8, size: 1.2 })] : undefined}>
      <GlslShader
        id="au-shader"
        width={W}
        height={H}
        fragment={FRAGMENT}
        uniforms={{
          u_res: [W, H],
          u_ph: ph,
          u_g0: rgb(p.groundTop),
          u_g1: rgb(p.groundBottom),
          u_c0: rgb(p.ribbons[0]),
          u_c1: rgb(p.ribbons[1]),
          u_c2: rgb(p.ribbons[2]),
          u_int: p.intensity,
          u_w: p.width,
          u_scale: p.scale,
        }}
      />
    </Layer>
  );
};

// Drift Gradient: big, out-of-focus pools of ultramarine and cyan that drift across an electric-blue field, with a teal
// cast along the edges, like a defocused light through water. Matched to a looping blue-gradient reference: its palette,
// the size of its pools (each about half the frame), their softness and their pace (a pool crosses a third of the frame
// in about four seconds). The reference loops every two minutes; this loops seamlessly every 10 s.
//
// One fragment shader: a few soft blobs, dark and bright, each travelling on its own closed Lissajous path (whole-number
// frequencies of the loop phase, so the loop is exact), blended into one field over a mid-blue base, gently warped by slow
// noise so the pools are never perfect circles, and mapped through the ramp navy, ultramarine, azure, sky, cyan. A second
// field of blobs near the edges tints toward teal.
//
// Principles: slow in and out (every path is a sine), overlap (each pool has its own path and period), arcs (closed
// curved paths), restraint (one hue family, no edges anywhere, no grain).

import React from 'react';
import { z } from 'zod';
import { GlslShader } from '@kinetographdev/core';
import { useCurrentFrame } from 'remotion';
import { rgb } from './lib.js';

export const W = 1920;
export const H = 1080;
export const LOOP = 300;

const hex = z.string().describe('A CSS colour as #rrggbb.');

export const driftGradientSchema = z.object({
  deep: hex.describe('The darkest pools (navy ultramarine).'),
  mid: hex.describe('The body of the field (electric blue).'),
  light: hex.describe('The lighter field around the bright pools (sky blue).'),
  glow: hex.describe('The brightest pools (cyan).'),
  tint: hex.describe('The cast along the edges (teal).'),
  scale: z.number().min(0.4).max(3).describe('Size of the pools: higher is larger.'),
  contrast: z.number().min(0).max(2).describe('How dark the dark pools and how bright the bright ones get. 1 matches the reference.'),
  speed: z.number().min(0).max(4).describe('Loops per 10 seconds. Whole numbers loop seamlessly.'),
});
export type DriftGradientProps = z.infer<typeof driftGradientSchema>;

export const driftGradientDefaults: DriftGradientProps = {
  deep: '#000c8c',
  mid: '#0052d0',
  light: '#00a2ee',
  glow: '#00dcf6',
  tint: '#0b8eaa',
  scale: 1,
  contrast: 1,
  speed: 1,
};

const FRAGMENT = `
precision highp float;
uniform vec2 u_res;
uniform float u_ph;
uniform vec3 u_deep; uniform vec3 u_mid; uniform vec3 u_light; uniform vec3 u_glow; uniform vec3 u_tint;
uniform float u_scale; uniform float u_contrast;

float hash(vec2 p){ p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p){
  vec2 i = floor(p); vec2 f = fract(p); f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float a = hash(i); float b = hash(i + vec2(1.0, 0.0)); float c = hash(i + vec2(0.0, 1.0)); float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
// a soft pool of radius s at c
// stretched along the rising diagonal, as the reference's pools are
float blob(vec2 p, vec2 c, float s){
  vec2 d = (p - c) / (s * u_scale);
  d = mat2(0.866, 0.5, -0.5, 0.866) * d;
  d.x *= 0.62;
  return exp(-dot(d, d));
}

void main(){
  vec2 uv = gl_FragCoord.xy / u_res;
  uv.y = 1.0 - uv.y;
  float asp = u_res.x / u_res.y;
  vec2 p = vec2(uv.x * asp, uv.y);
  float ph = u_ph;

  // a slow warp so the pools wobble out of round; its offsets go round a circle once per loop
  vec2 o = 0.6 * vec2(cos(ph), sin(ph));
  p += 0.12 * (vec2(vnoise(p * 1.4 + o), vnoise(p * 1.4 + vec2(5.3, 2.1) - o)) - 0.5);

  // the pools, each a value (0 the darkest, 1 the brightest) that pulls the field toward it near its centre: a weighted
  // average, like a mesh gradient, so overlapping pools blend instead of piling up
  float acc = 0.0; float wsum = 0.0; float w;
  #define POOL(v, c, s) w = pow(blob(p, c, s), 1.8); acc += w * (0.55 + ((v) - 0.55) * u_contrast); wsum += w;
  POOL(0.05, vec2(0.62 * asp + 0.42 * cos(ph + 2.4), 0.42 + 0.28 * sin(ph + 0.9) + 0.06 * sin(2.0 * ph)), 0.5)
  POOL(0.22, vec2(0.3 * asp + 0.35 * cos(ph + 5.0) + 0.1 * cos(2.0 * ph + 1.0), 0.78 + 0.22 * sin(ph + 3.9)), 0.42)
  POOL(0.3,  vec2(0.8 * asp + 0.3 * cos(2.0 * ph + 0.3), 0.82 + 0.18 * cos(ph + 1.7)), 0.42)
  POOL(0.42, vec2(0.15 * asp + 0.25 * cos(ph + 0.6), 0.55 + 0.3 * sin(ph + 5.6)), 0.4)
  POOL(1.0,  vec2(0.7 * asp + 0.4 * cos(ph + 0.4), 0.45 + 0.3 * sin(ph + 4.3) + 0.05 * cos(2.0 * ph + 2.0)), 0.5)
  POOL(0.88, vec2(0.25 * asp + 0.4 * sin(ph + 1.2), 0.2 + 0.2 * cos(ph + 0.2)), 0.42)
  POOL(0.78, vec2(0.55 * asp + 0.35 * cos(2.0 * ph + 4.1), 0.05 + 0.12 * sin(ph + 2.2)), 0.36)
  // the electric-blue field everywhere between them
  acc += 0.02 * 0.55; wsum += 0.02;
  float f = clamp(acc / wsum, 0.0, 1.0);

  // the ramp: navy, ultramarine, electric blue, sky, cyan
  vec3 col = mix(u_deep, u_mid, smoothstep(0.05, 0.45, f));
  col = mix(col, u_light, smoothstep(0.34, 0.74, f));
  col = mix(col, u_glow, smoothstep(0.72, 1.0, f));

  // the teal cast, strongest near the left and top edges, drifting along them
  float tl = blob(p, vec2(-0.05 + 0.08 * cos(ph + 1.0), 0.35 + 0.3 * sin(ph + 0.4)), 0.42)
           + 0.7 * blob(p, vec2(0.35 * asp + 0.4 * cos(ph + 3.0), -0.08), 0.35);
  col = mix(col, u_tint, clamp(tl, 0.0, 1.0) * 0.38 * smoothstep(0.15, 0.55, f) * smoothstep(0.95, 0.6, f));

  gl_FragColor = vec4(col, 1.0);
}
`;

export const DriftGradient: React.FC<DriftGradientProps> = (p) => {
  const frame = useCurrentFrame();
  const ph = (2 * Math.PI * frame * p.speed) / LOOP;
  return (
    <GlslShader
      id="dg-shader"
      width={W}
      height={H}
      fragment={FRAGMENT}
      uniforms={{
        u_res: [W, H],
        u_ph: ph,
        u_deep: rgb(p.deep),
        u_mid: rgb(p.mid),
        u_light: rgb(p.light),
        u_glow: rgb(p.glow),
        u_tint: rgb(p.tint),
        u_scale: p.scale,
        u_contrast: p.contrast,
      }}
    />
  );
};

// Grain Flow: two soft sheets of light, cobalt to ice white, that flow past a dark navy valley like slow liquid, under
// fine film grain. Matched to a still gradient reference: the dark valley runs from the top left to the lower right, one
// sheet of blue fills the top right and fades to pale blue in the corner, the other fills the lower left and burns to
// near white in its corner. Here the sheets breathe and undulate on a seamless 10 s loop.
//
// One fragment shader: each edge of the valley is a curve that waves over the loop; the frame is warped by slow noise
// whose offsets move on closed circles (so the loop is exact); brightness is the soft distance from each edge plus a glow
// from its corner, mapped through the ramp navy, cobalt, blue, pale blue, white; then grain, new every frame and seeded
// by the frame number, is added on top.
//
// Principles: slow in and out (every motion is a sine of the loop phase), overlap (the two sheets and the warp each run
// on their own phase), arcs (noise offsets travel on circles), restraint (one hue, no hard edges), texture on the whole
// frame (the grain).

import React from 'react';
import { z } from 'zod';
import { GlslShader } from '@kinetographdev/core';
import { useCurrentFrame } from 'remotion';
import { rgb } from './lib.js';

export const W = 1920;
export const H = 1080;
export const LOOP = 300;

const hex = z.string().describe('A CSS colour as #rrggbb.');

export const grainFlowSchema = z.object({
  ground: hex.describe('The dark valley between the sheets (navy black).'),
  deep: hex.describe('The body colour of the sheets (cobalt).'),
  bright: hex.describe('The lit part of the sheets toward their corners (sky blue).'),
  glow: hex.describe('The hottest light, in the lower-left corner (ice white).'),
  flow: z.number().min(0).max(2).describe('How far the sheets bend and travel over the loop. 1 is a slow liquid drift.'),
  speed: z.number().min(0).max(4).describe('Loops per 10 seconds. Whole numbers loop seamlessly.'),
  grain: z.number().min(0).max(1).describe('Film grain strength. 0.5 matches the reference.'),
});
export type GrainFlowProps = z.infer<typeof grainFlowSchema>;

export const grainFlowDefaults: GrainFlowProps = {
  ground: '#0f121a',
  deep: '#1438a0',
  bright: '#5486d0',
  glow: '#eef0ea',
  flow: 1,
  speed: 1,
  grain: 0.5,
};

const FRAGMENT = `
precision highp float;
uniform vec2 u_res;
uniform float u_ph;
uniform float u_seed;
uniform vec3 u_ground; uniform vec3 u_deep; uniform vec3 u_bright; uniform vec3 u_glow;
uniform float u_flow; uniform float u_grain;

float hash(vec2 p){ p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p){
  vec2 i = floor(p); vec2 f = fract(p); f = f * f * (3.0 - 2.0 * f);
  float a = hash(i); float b = hash(i + vec2(1.0, 0.0)); float c = hash(i + vec2(0.0, 1.0)); float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p){ return 0.65 * vnoise(p) + 0.35 * vnoise(p * 2.1 + 7.3); }
vec2 orbit(float ph, float r, float k){ return r * vec2(cos(ph + k), sin(ph + k * 1.7)); }

// the colour ramp: navy, cobalt, blue, pale blue, white
vec3 ramp(float f){
  vec3 c = mix(u_ground, u_deep, smoothstep(0.0, 0.5, f));
  c = mix(c, u_bright, smoothstep(0.55, 0.78, f));
  c = mix(c, mix(u_bright, u_glow, 0.55), smoothstep(0.76, 0.9, f));
  return mix(c, u_glow, smoothstep(0.9, 1.0, f));
}

void main(){
  vec2 uv = gl_FragCoord.xy / u_res;
  uv.y = 1.0 - uv.y;
  vec2 a = vec2(uv.x * (u_res.x / u_res.y), uv.y);

  // liquid: the whole frame drifts on slow noise whose offsets go round a circle once per loop
  vec2 w = vec2(fbm(a * 1.3 + orbit(u_ph, 0.7, 0.0)), fbm(a * 1.3 + vec2(4.1, 7.3) + orbit(u_ph, 0.7, 2.3))) - 0.5;
  vec2 q = uv + w * 0.16 * u_flow;
  float x = q.x;

  // the upper sheet's edge: from the top a quarter in, down to 40% at the right, with a tongue that waves
  float yU = -0.08 + 1.05 * x - 0.5 * x * x + 0.045 * u_flow * sin(x * 4.0 + u_ph) + 0.03 * u_flow * sin(u_ph * 2.0 + 1.3);
  // the lower sheet's edge: 58% down at the left, out of the frame at the lower right
  float yL = 0.55 + 0.1 * x + 0.22 * x * x + 0.05 * u_flow * sin(x * 3.2 - u_ph + 2.0) + 0.03 * u_flow * sin(u_ph * 2.0 + 4.0);

  float up = smoothstep(-0.06, 0.24, yU - q.y);
  float lo = smoothstep(-0.06, 0.24, q.y - yL);

  // corner light: pale blue at the top right, near white at the lower left; each breathes a little over the loop
  float gTR = smoothstep(0.66, 0.0, length((q - vec2(1.05, -0.06)) * vec2(1.0, 1.25)));
  float gBL = smoothstep(0.74, 0.0, length((q - vec2(-0.06, 1.06)) * vec2(1.0, 1.3)));
  gTR *= 0.9 + 0.1 * sin(u_ph + 0.5);
  gBL *= 0.92 + 0.08 * sin(u_ph + 3.6);

  float f = max(up * (0.5 + 0.42 * gTR), lo * (0.5 + 0.62 * gBL));
  f = clamp(f, 0.0, 1.0);
  vec3 col = ramp(f);

  // film grain, a new pattern every frame, a touch stronger in the mid tones
  // soft grains about 1.5 px across, as on a scanned print
  vec2 gp = mod(gl_FragCoord.xy, 384.0) / 1.5 + vec2(fract(u_seed * 0.618034), fract(u_seed * 0.754878)) * 97.0;
  float n = (vnoise(gp) + vnoise(gp * 1.9 + 13.7) - 1.0) * 1.6;
  float lum = dot(col, vec3(0.299, 0.587, 0.114));
  col += n * u_grain * (0.07 + 0.05 * (1.0 - abs(lum * 2.0 - 1.0)));
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
`;

export const GrainFlow: React.FC<GrainFlowProps> = (p) => {
  const frame = useCurrentFrame();
  const ph = (2 * Math.PI * frame * p.speed) / LOOP;
  return (
    <GlslShader
      id="gf-shader"
      width={W}
      height={H}
      fragment={FRAGMENT}
      uniforms={{
        u_res: [W, H],
        u_ph: ph,
        u_seed: frame % LOOP,
        u_ground: rgb(p.ground),
        u_deep: rgb(p.deep),
        u_bright: rgb(p.bright),
        u_glow: rgb(p.glow),
        u_flow: p.flow,
        u_grain: p.grain,
      }}
    />
  );
};

// Grain Gradient: a soft mesh of colour that drifts slowly, with fine film grain over it. Twelve mesh points take colours
// from the palette and each wanders on a small closed loop, so the field breathes and comes back to where it began. The
// mesh is drawn past the frame and blurred, so its patches never show.
//
// Principles: slow in and out (every point moves on a sine), overlap (each point has its own phase, so nothing moves
// together), arcs (closed elliptical paths), restraint (movement under a tenth of a cell), texture makes it made (grain on
// the whole frame, not per element).

import React from 'react';
import { z } from 'zod';
import { Layer, MeshGradient, Rect, blur, grain } from '@kinetographdev/core';
import { useCurrentFrame } from 'remotion';
import { phase } from './lib.js';

export const W = 1920;
export const H = 1080;
export const FPS = 30;
export const DURATION = 300;

const hex = z.string().describe('A CSS colour.');

export const grainGradientSchema = z.object({
  palette: z.array(hex).min(2).max(8).describe('Colours of the mesh, spread over its points in a fixed pattern. Two to eight.'),
  speed: z.number().min(0).max(4).describe('How fast the field drifts. Whole numbers loop seamlessly over 10 seconds.'),
  scale: z.number().min(0.3).max(3).describe('How far the points wander, as a multiple of the default. 1 is about a tenth of a cell.'),
  softness: z.number().min(0).max(120).describe('Blur over the mesh in pixels: higher is smoother, lower shows more of the patches.'),
  grain: z.number().min(0).max(0.5).describe('Grain amount. 0.1 is a visible film grain.'),
  grainSize: z.number().min(1).max(4).describe('Size of a grain cell in pixels.'),
});
export type GrainGradientProps = z.infer<typeof grainGradientSchema>;

export const grainGradientDefaults: GrainGradientProps = {
  palette: ['#f6d9c3', '#e9a58d', '#7b8fd6', '#f3efe6', '#4a5aa8'],
  speed: 1,
  scale: 1,
  softness: 0,
  grain: 0.14,
  grainSize: 1.3,
};

const COLS = 4;
const ROWS = 3;
const OVER = 420; // how far the mesh extends past the frame

export const GrainGradient: React.FC<GrainGradientProps> = (p) => {
  const frame = useCurrentFrame();
  const ph = phase(frame, DURATION, p.speed);
  const bw = W + 2 * OVER;
  const bh = H + 2 * OVER;
  const cw = bw / (COLS - 1);
  const ch = bh / (ROWS - 1);
  const amp = 0.18 * p.scale;
  const points: [number, number][] = [];
  const colors: string[] = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const i = r * COLS + c;
      // edge points slide along the edge only, so the mesh keeps covering the frame
      const dx = c === 0 || c === COLS - 1 ? 0 : amp * cw * Math.sin(ph * (1 + (i % 2)) + i * 1.9);
      const dy = r === 0 || r === ROWS - 1 ? 0 : amp * ch * Math.cos(ph * (1 + ((i + 1) % 2)) + i * 2.7);
      const ex = r === 0 || r === ROWS - 1 ? amp * cw * 0.8 * Math.sin(ph + i * 1.3) : 0;
      const ey = c === 0 || c === COLS - 1 ? amp * ch * 0.8 * Math.cos(ph + i * 0.9) : 0;
      points.push([c * cw + dx + ex, r * ch + dy + ey]);
      colors.push(p.palette[(r * 2 + c * 3 + (r % 2)) % p.palette.length]);
    }
  }
  return (
    <Layer id="gg-root" effects={p.grain > 0 ? [grain(p.grain, { seed: 3, size: p.grainSize })] : undefined}>
      <Rect id="gg-base" width={W} height={H} fill={p.palette[0]} />
      <Layer id="gg-mesh" x={-OVER} y={-OVER} effects={p.softness > 0 ? [blur(p.softness)] : undefined}>
        <MeshGradient id="gg-m" width={bw} height={bh} columns={COLS} rows={ROWS} points={points} colors={colors} />
      </Layer>
    </Layer>
  );
};

// Shared bits for the backgrounds: colour parsing for shader uniforms, the loop phase, and the GLSL noise every shader uses.

/** "#rrggbb" or "#rgb" to [r, g, b] in 0..1 for a vec3 uniform. */
export const rgb = (hex: string): [number, number, number] => {
  let h = hex.replace('#', '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  const n = parseInt(h.slice(0, 6), 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
};

/** Phase in radians that completes a whole turn over `loop` frames, scaled by speed. A whole number of turns per loop
 *  (speed 1, 2, 3 ...) makes the clip loop without a seam; other speeds drift without looping. */
export const phase = (frame: number, loop: number, speed: number) => (2 * Math.PI * frame * speed) / loop;

export const NOISE_GLSL = `
float hash(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
float vnoise(vec2 p){
  vec2 i=floor(p); vec2 f=fract(p); f=f*f*(3.0-2.0*f);
  float a=hash(i); float b=hash(i+vec2(1.0,0.0)); float c=hash(i+vec2(0.0,1.0)); float d=hash(i+vec2(1.0,1.0));
  return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);
}
float fbm(vec2 p){
  float v=0.0; float a=0.5;
  for(int i=0;i<5;i++){ v+=a*vnoise(p); p=p*2.02+17.1; a*=0.5; }
  return v;
}
`;

// Liquid Gradient: a slow pour of deep plum, crimson and amber that folds over itself and comes back to where it began,
// matched to a 10 s looping gradient reference. It is calm at the loop point (big soft pools of plum and amber) and swirls
// in the middle of the loop (amber ribbons drawn into S-curves through the plum), then settles again, so the seam is
// invisible.
//
// One fragment shader: fbm noise, warped twice by itself (domain warping), with every offset moving on a closed circle so
// the loop is exact. The warp's strength breathes over the loop, which gives the calm, swirl, calm rhythm. Colour comes
// from the warp fields: the plum where the field is low, amber where it is high, crimson pooled on one side and along
// the boundary between them, as in the reference.
//
// Principles: slow in and out (the warp eases in and out over the loop), follow through and overlapping action (each
// warp layer lags the one under it), arcs (the field travels on circles), restraint (three colours, no grain, no light).

import React from 'react';
import { z } from 'zod';
import { GlslShader } from '@kinetographdev/core';
import { useCurrentFrame } from 'remotion';
import { rgb } from './lib.js';

export const W = 1920;
export const H = 1080;
export const FPS = 30;
export const LOOP = 300;

const hex = z.string().describe('A CSS colour as #rrggbb.');

export const liquidGradientSchema = z.object({
  deep: hex.describe('The darkest colour, where the field is low (plum).'),
  mid: hex.describe('The colour pooled along one side and between the others (crimson).'),
  bright: hex.describe('The brightest colour, where the field is high (amber).'),
  scale: z.number().min(0.4).max(3).describe('Size of the shapes: higher is larger, calmer pools.'),
  swirl: z.number().min(0).max(2).describe('How far the shapes fold over in the middle of the loop. 1 matches the reference.'),
  speed: z.number().min(0).max(4).describe('Loops per 10 seconds. Whole numbers loop seamlessly.'),
  softness: z.number().min(0).max(1).describe('How soft the edges between colours are.'),
});
export type LiquidGradientProps = z.infer<typeof liquidGradientSchema>;

export const liquidGradientDefaults: LiquidGradientProps = {
  deep: '#22002e',
  mid: '#c4002f',
  bright: '#f0883a',
  scale: 1,
  swirl: 1,
  speed: 1,
  softness: 0.8,
};

const FRAGMENT = `
precision highp float;
uniform vec2 u_res;
uniform float u_ph;
uniform vec3 u_deep; uniform vec3 u_mid; uniform vec3 u_bright;
uniform float u_scale; uniform float u_swirl; uniform float u_soft;

float hash(vec2 p){ p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p){
  vec2 i = floor(p); vec2 f = fract(p); f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float a = hash(i); float b = hash(i + vec2(1.0, 0.0)); float c = hash(i + vec2(0.0, 1.0)); float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p){
  float v = 0.0; float a = 0.5; float n = 0.0;
  mat2 r = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 2; i++){ v += a * vnoise(p); n += a; p = r * p * 2.03 + 11.7; a *= 0.5; }
  return v / n;
}
// a point that goes once round a circle per loop
vec2 orbit(float ph, float r, float k){ return r * vec2(cos(ph + k), sin(ph * 1.0 + k * 1.7)); }

void main(){
  vec2 uv = gl_FragCoord.xy / u_res;
  uv.y = 1.0 - uv.y;
  vec2 p = vec2(uv.x * (u_res.x / u_res.y), uv.y) * (0.95 / u_scale);

  // calm at the loop point, folded in the middle
  float breathe = 0.5 - 0.5 * cos(u_ph);
  float amp = (0.7 + 1.5 * breathe) * u_swirl;

  vec2 q = vec2(fbm(p + orbit(u_ph, 0.55, 0.0)), fbm(p + vec2(5.2, 1.3) + orbit(u_ph, 0.55, 2.1)));
  vec2 r = vec2(fbm(p + amp * q + vec2(1.7, 9.2) + orbit(u_ph, 0.35, 4.0)), fbm(p + amp * q + vec2(8.3, 2.8) + orbit(u_ph, 0.35, 1.0)));
  float f = fbm(p + amp * r + orbit(u_ph, 0.25, 3.0));
  // the warped field bunches around 0.3; spread it over 0..1
  f = clamp((f - 0.1) / 0.42, 0.0, 1.0);
  // the plum gathers toward the top left, the amber toward the lower right, as in the reference
  f += 0.22 * (uv.x * 0.6 + uv.y * 0.4 - 0.5);

  float s = mix(0.05, 0.34, u_soft);
  // amber where the field is high, plum where it is low, the brown of the two between
  float t = smoothstep(0.42 - s, 0.58 + s, f);
  vec3 col = mix(u_deep, u_bright, t);
  // crimson: pooled toward the lower left, and along the edge of the plum
  float pool = smoothstep(0.85, 0.1, length((uv - vec2(-0.05, 0.8)) * vec2(1.0, 1.2))) * smoothstep(0.7, 0.4, r.x) * smoothstep(0.18, 0.42, f);
  float edge = smoothstep(0.30, 0.46, f) * smoothstep(0.62, 0.46, f) * smoothstep(0.35, 0.6, q.y);
  col = mix(col, u_mid, clamp(pool * 0.95 + edge * 0.4, 0.0, 0.85));
  // the plum deepest in its pools
  col = mix(col, u_deep * 0.9, smoothstep(0.38, 0.15, f) * 0.6);
  gl_FragColor = vec4(col, 1.0);
}
`;

export const LiquidGradient: React.FC<LiquidGradientProps> = (p) => {
  const frame = useCurrentFrame();
  const ph = (2 * Math.PI * frame * p.speed) / LOOP;
  return (
    <GlslShader
      id="lg-shader"
      width={W}
      height={H}
      fragment={FRAGMENT}
      uniforms={{
        u_res: [W, H],
        u_ph: ph,
        u_deep: rgb(p.deep),
        u_mid: rgb(p.mid),
        u_bright: rgb(p.bright),
        u_scale: p.scale,
        u_swirl: p.swirl,
        u_soft: p.softness,
      }}
    />
  );
};

// Rise Glow: a dark ground with a soft band of light rising from the bottom edge in two humps (brightest in the bottom
// corners, dipping in the middle), and a faint ring sweeping round the left. Taken from the opening of a SaaS launch
// reel and measured there: the ground #121013, the band's
// top edge at 0.31 H in the corners and 0.15 H in the middle, its colours from #4a1c1a at the edge through #a54e41 to
// #cc887e in the corners, and the ring #1e1313. The reference's glow does not loop; here the humps sway and breathe on a
// seamless 10 s loop.
//
// `palette` swaps the ramp for the colours of another background in this folder (Liquid, Drift, Tide, Flow, Aurora,
// Veil, Grain), read from that component's own defaults, so a variation always matches its source. `colors` overrides
// both with your own five.
//
// One fragment shader: the light falls off upward from the bottom edge as A·exp(-(y/L)^1.3), where the strength A and the
// reach L are slow sines across x (two humps; whole-number frequencies of the loop phase), mapped through the five-colour
// ramp.
//
// Principles: slow in and out (every motion is a sine), overlap (the two humps sway on different phases), restraint (one
// light, no edges, no grain).

import React from 'react';
import { z } from 'zod';
import { GlslShader } from '@kinetographdev/core';
import { useCurrentFrame } from 'remotion';
import { rgb } from './lib.js';
import { liquidGradientDefaults as liquid } from './liquid-gradient.js';
import { driftGradientDefaults as drift } from './drift-gradient.js';
import { tideGradientDefaults as tide } from './tide-gradient.js';
import { grainFlowDefaults as flow } from './grain-flow.js';
import { auroraDefaults as aurora } from './aurora.js';
import { auroraVeilDefaults as veil } from './aurora-veil.js';
import { grainGradientDefaults as grain } from './grain-gradient.js';

export const W = 1920;
export const H = 1080;
export const LOOP = 300;

/** Mix two #rrggbb colours (t 0..1) and return #rrggbb. */
const mixHex = (a: string, b: string, t: number) => {
  const [x, y] = [rgb(a), rgb(b)];
  return '#' + x.map((v, i) => Math.round((v + (y[i] - v) * t) * 255).toString(16).padStart(2, '0')).join('');
};

/** Each palette is [ground, edge, body, hot, core]: the dark field, the band's outer edge, its body, the corners, and the
 *  brightest point at the bottom of the corners. */
export const RISE_PALETTES = {
  ember: ['#121013', '#4a1c1a', '#a54e41', '#cc887e', '#ead2cf'],
  liquid: [mixHex(liquid.deep, '#000000', 0.6), liquid.deep, liquid.mid, liquid.bright, mixHex(liquid.bright, '#ffffff', 0.55)],
  drift: [mixHex(drift.deep, '#000000', 0.82), drift.deep, drift.mid, drift.light, drift.glow],
  tide: [tide.ground, tide.colors[5], tide.colors[2], tide.colors[1], tide.colors[0]],
  flow: [flow.ground, flow.deep, mixHex(flow.deep, flow.bright, 0.6), flow.bright, flow.glow],
  aurora: [aurora.groundTop, aurora.ribbons[1], aurora.ribbons[2], aurora.ribbons[0], mixHex(aurora.ribbons[0], '#ffffff', 0.55)],
  veil: ['#04120d', veil.colors[4], veil.colors[0], veil.colors[1], veil.colors[2]],
  grain: [mixHex(grain.palette[4], '#000000', 0.8), grain.palette[4], grain.palette[2], grain.palette[1], grain.palette[0]],
} as const;
export type RisePalette = keyof typeof RISE_PALETTES;

const hex = z.string().describe('A CSS colour as #rrggbb.');

export const riseGlowSchema = z.object({
  palette: z.enum(Object.keys(RISE_PALETTES) as [RisePalette, ...RisePalette[]]).describe(
    'The colours: ember is the reference; the others take the colours of LiquidGradient, DriftGradient, TideGradient, GrainFlow, Aurora, AuroraVeil and GrainGradient.',
  ),
  colors: z.array(hex).length(5).optional().describe('Your own five colours (ground, edge, body, hot, core); overrides palette.'),
  height: z.number().min(0.3).max(2.5).describe('How high the band rises. 1 matches the reference (0.31 H in the corners).'),
  dip: z.number().min(0).max(1).describe('How far the middle sinks between the two humps. 1 matches the reference.'),
  ring: z.number().min(0).max(1).describe('Strength of the faint ring at the left. 1 matches the reference, 0 hides it.'),
  sway: z.number().min(0).max(3).describe('How much the humps sway and breathe.'),
  speed: z.number().min(0).max(4).describe('Loops per 10 seconds. Whole numbers loop seamlessly.'),
});
export type RiseGlowProps = z.infer<typeof riseGlowSchema>;

export const riseGlowDefaults: RiseGlowProps = {
  palette: 'ember',
  height: 1,
  dip: 1,
  ring: 1,
  sway: 1,
  speed: 1,
};

const FRAGMENT = `
precision highp float;
uniform vec2 u_res;
uniform float u_ph;
uniform vec3 u_c0; uniform vec3 u_c1; uniform vec3 u_c2; uniform vec3 u_c3; uniform vec3 u_c4;
uniform float u_height; uniform float u_dip; uniform float u_ring; uniform float u_sway;

void main(){
  vec2 px = gl_FragCoord.xy;
  float x = px.x / u_res.x;
  float b = px.y / u_res.y;            // height above the bottom edge, 0..1
  float ph = u_ph;

  // the light falls off upward from the bottom edge, strongest and tallest in the corners, lower in the middle; fitted
  // to the reference's columns (corners 0.85 / 0.6 / 0.4 / 0.15 at 0.06 / 0.17 / 0.28 / 0.39 H, the middle 0.55 / 0.3 / 0.1)
  float sx = x + 0.035 * u_sway * sin(ph + 0.7);
  float c = cos(6.2831853 * sx);
  float A = 0.75 + 0.22 * u_dip * c + 0.06 * x + 0.03 * u_sway * sin(2.0 * ph + 6.2831853 * x * 2.0);
  float L = (0.18 + 0.045 * u_dip * c + 0.035 * x + 0.01 * u_sway * sin(ph + 1.9)) * u_height;
  float v = clamp(A * exp(-pow(b / L, 1.3)), 0.0, 1.0);

  vec3 col = mix(u_c0, u_c1, smoothstep(0.0, 0.18, v));
  col = mix(col, u_c2, smoothstep(0.15, 0.5, v));
  col = mix(col, u_c3, smoothstep(0.45, 0.85, v));
  col = mix(col, u_c4, smoothstep(0.85, 1.0, v) * 0.6);

  // the faint ring: an annulus round a point on the left edge, the ground lifted slightly toward the band's edge colour
  float r = length(px - vec2(0.0, 0.5 * u_res.y)) / u_res.y;
  float rin = 0.47 + 0.02 * sin(ph + 0.3);
  float rout = 0.7 + 0.015 * sin(ph + 2.1);
  float ring = smoothstep(rin - 0.004, rin + 0.004, r) * (1.0 - smoothstep(rout - 0.004, rout + 0.004, r));
  // it lifts the ground by at most 0.05 per channel (the reference's #1e1313 on #121013), whatever the palette
  vec3 dd = u_c1 - u_c0;
  float k = min(0.3, 0.05 / max(max(abs(dd.r), abs(dd.g)), max(abs(dd.b), 0.001)));
  col = mix(col, u_c0 + dd * k, ring * u_ring * (1.0 - smoothstep(0.0, 0.3, v)));

  gl_FragColor = vec4(col, 1.0);
}
`;

export const RiseGlow: React.FC<RiseGlowProps> = (p) => {
  const frame = useCurrentFrame();
  const ph = (2 * Math.PI * frame * p.speed) / LOOP;
  const c = p.colors ?? RISE_PALETTES[p.palette];
  return (
    <GlslShader
      id="rg-shader"
      width={W}
      height={H}
      fragment={FRAGMENT}
      uniforms={{
        u_res: [W, H],
        u_ph: ph,
        u_c0: rgb(c[0]),
        u_c1: rgb(c[1]),
        u_c2: rgb(c[2]),
        u_c3: rgb(c[3]),
        u_c4: rgb(c[4]),
        u_height: p.height,
        u_dip: p.dip,
        u_ring: p.ring,
        u_sway: p.sway,
      }}
    />
  );
};

// Tide Gradient: quick, soft pools of cyan, mint, teal and steel blue that swell, slide over one another and sink into
// black, like light moving under water. Matched to a 15 s gradient reference: its palette (black through deep teal and
// steel blue to mint and cyan), the size of its pools (each a half to two thirds of the frame), their softness, the
// black that opens between them, and their pace (much faster than the other gradients: the picture
// changes by about a tenth of its brightness every half second). The reference does not loop; this one loops on 10 s.
//
// One fragment shader: six pools, each with its own colour, travelling on its own closed path (whole-number multiples
// of the loop phase, so the loop is exact) and swelling and fading on its own beat. Each pixel's colour is the pools'
// colours averaged by how close it is to each (a mesh gradient), and its brightness is how strongly any pool reaches it,
// so where no pool reaches the frame falls to black. A slow noise warp keeps the pools from being perfect circles.
//
// Principles: overlap (six paths and six beats that never line up), slow in and out (every path and beat is a sine),
// arcs (closed curved paths), restraint (one cool family; no grain, no light streaks).

import React from 'react';
import { z } from 'zod';
import { GlslShader } from '@kinetographdev/core';
import { useCurrentFrame } from 'remotion';
import { rgb } from './lib.js';

export const W = 1920;
export const H = 1080;
export const LOOP = 300;

const hex = z.string().describe('A CSS colour as #rrggbb.');

export const tideGradientSchema = z.object({
  colors: z.array(hex).length(6).describe('The six pool colours: by default cyan, mint, sea green, blue, steel and deep teal.'),
  ground: hex.describe('What shows where no pool reaches (black).'),
  scale: z.number().min(0.4).max(3).describe('Size of the pools: higher is larger.'),
  depth: z.number().min(0).max(2).describe('How much black opens between the pools. 1 matches the reference; 0 fills the frame.'),
  speed: z.number().min(0).max(4).describe('Loops per 10 seconds. Whole numbers loop seamlessly.'),
});
export type TideGradientProps = z.infer<typeof tideGradientSchema>;

export const tideGradientDefaults: TideGradientProps = {
  colors: ['#40eafd', '#2ad0ae', '#1a8a7e', '#2a8ed0', '#1b5d7c', '#0d3a52'],
  ground: '#000000',
  scale: 1,
  depth: 1,
  speed: 1,
};

const FRAGMENT = `
precision highp float;
uniform vec2 u_res;
uniform float u_ph;
uniform vec3 u_c0; uniform vec3 u_c1; uniform vec3 u_c2; uniform vec3 u_c3; uniform vec3 u_c4; uniform vec3 u_c5;
uniform vec3 u_ground;
uniform float u_scale; uniform float u_depth;

float hash(vec2 p){ p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p){
  vec2 i = floor(p); vec2 f = fract(p); f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float a = hash(i); float b = hash(i + vec2(1.0, 0.0)); float c = hash(i + vec2(0.0, 1.0)); float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

vec3 acc; float wsum; float reach;
// a pool of colour c, radius s, at centre m, with strength k (0..1): a soft body, brightest at its centre
void pool(vec2 p, vec2 m, float s, vec3 c, float k){
  float d = length(p - m) / (s * u_scale);
  float body = exp(-d * d * 1.5);
  float w = k * body + 1e-4;
  acc += c * w * w; wsum += w * w;
  reach += w;
}

void main(){
  vec2 uv = gl_FragCoord.xy / u_res;
  uv.y = 1.0 - uv.y;
  float asp = u_res.x / u_res.y;
  vec2 p = vec2(uv.x * asp, uv.y);
  float ph = u_ph;

  // a slow warp so the pools wobble; its offsets go round a circle once per loop
  vec2 o = 0.8 * vec2(cos(u_ph), sin(u_ph));
  p += 0.1 * (vec2(vnoise(p * 1.6 + o), vnoise(p * 1.6 + vec2(3.7, 8.1) - o)) - 0.5);

  acc = vec3(0.0); wsum = 0.0; reach = 0.0;
  pool(p, vec2(0.55 + 0.55 * cos(2.0 * ph + 0.3) + 0.15 * cos(3.0 * ph), 0.3 + 0.32 * sin(3.0 * ph + 1.0)), 0.48, u_c0, 0.65 + 0.35 * sin(2.0 * ph + 0.5));
  pool(p, vec2(0.6 + 0.5 * cos(3.0 * ph + 2.2), 0.55 + 0.4 * sin(2.0 * ph + 3.0) + 0.1 * sin(ph)), 0.58, u_c1, 0.7 + 0.3 * sin(3.0 * ph + 2.0));
  pool(p, vec2(0.45 + 0.45 * sin(ph + 4.0) + 0.2 * sin(3.0 * ph + 1.0), 0.45 + 0.35 * cos(2.0 * ph + 0.4)), 0.62, u_c2, 0.75 + 0.25 * sin(ph + 1.0));
  pool(p, vec2(1.35 + 0.45 * cos(2.0 * ph + 1.4) + 0.12 * sin(3.0 * ph + 1.0), 0.6 + 0.4 * sin(3.0 * ph + 2.6)), 0.66, u_c3, 0.75 + 0.3 * sin(2.0 * ph + 4.0));
  pool(p, vec2(1.2 + 0.55 * sin(3.0 * ph + 5.0), 0.35 + 0.45 * cos(2.0 * ph + 0.9)), 0.66, u_c4, 0.8 + 0.2 * sin(3.0 * ph + 0.2));
  pool(p, vec2(0.9 + 0.7 * cos(ph + 3.3) + 0.2 * cos(2.0 * ph), 0.75 + 0.3 * sin(3.0 * ph + 1.7)), 0.7, u_c5, 0.75 + 0.25 * sin(2.0 * ph + 5.5));

  vec3 col = acc / wsum;
  // brightness follows how strongly the pools reach a pixel, so each pool glows at its heart, overlaps run brighter,
  // and the gaps sink to the ground colour
  float lit = smoothstep(0.1 * u_depth, 0.1 * u_depth + 1.15, reach);
  col = mix(u_ground, col * (0.7 + 0.4 * lit), pow(lit, 1.25));
  gl_FragColor = vec4(col, 1.0);
}
`;

export const TideGradient: React.FC<TideGradientProps> = (p) => {
  const frame = useCurrentFrame();
  const ph = (2 * Math.PI * frame * p.speed) / LOOP;
  const c = (i: number) => rgb(p.colors[i]);
  return (
    <GlslShader
      id="tg-shader"
      width={W}
      height={H}
      fragment={FRAGMENT}
      uniforms={{
        u_res: [W, H],
        u_ph: ph,
        u_c0: c(0), u_c1: c(1), u_c2: c(2), u_c3: c(3), u_c4: c(4), u_c5: c(5),
        u_ground: rgb(p.ground),
        u_scale: p.scale,
        u_depth: p.depth,
      }}
    />
  );
};
